package main

import (
	"fmt"
	"os"
	"path"
	"regexp"
	"slices"
	"strconv"
	"strings"
)

var defaultGenerateArgs = []string{"--abi", strconv.Itoa(maxABI)}

// cliVersionPattern takes the whole version npx printed, prerelease and build
// metadata included. Matching only the numeric core recorded 0.25.0 for the
// 0.25.0-rc.1 that actually generated the vendored bytes, so the pin that is
// supposed to reproduce them would have run a different build of the
// generator, and nothing would have said so.
var cliVersionPattern = regexp.MustCompile(`\b\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]*[0-9A-Za-z])?(?:\+[0-9A-Za-z.-]*[0-9A-Za-z])?`)

// wantsGeneration reports whether this run regenerates the parser.
func wantsGeneration(existing Grammar, o options) bool {
	return o.Generate || o.TreeSitterCLI != "" || (existing.LocalBuild != nil && existing.LocalBuild.TreeSitterCLI != "")
}

// cliVersion picks the tree-sitter-cli to run: an explicit override, else
// the recorded version when regenerating the recorded revision (so the
// output is reproducible), else latest.
func cliVersion(existing Grammar, revision string, o options) string {
	if o.TreeSitterCLI != "" {
		return o.TreeSitterCLI
	}
	if existing.LocalBuild != nil && existing.LocalBuild.TreeSitterCLI != "" && existing.Revision == revision {
		return existing.LocalBuild.TreeSitterCLI
	}
	return "latest"
}

func generateArgs(build *LocalBuild) []string {
	if build != nil && len(build.GenerateArgs) > 0 {
		return build.GenerateArgs
	}
	return defaultGenerateArgs
}

// resolveCLI turns a version spec such as "latest" into the exact version
// npx runs, so generation and the manifest use the same one.
func resolveCLI(dir, spec string) (string, error) {
	out, err := npx(dir, "tree-sitter-cli@"+spec, "--version")
	if err != nil {
		return "", fmt.Errorf("tree-sitter-cli@%s --version: %w", spec, err)
	}
	version := cliVersionPattern.FindString(out)
	if version == "" {
		return "", fmt.Errorf("tree-sitter-cli@%s --version printed no version: %q", spec, out)
	}
	return version, nil
}

func generate(grammarRoot, version string, args []string) error {
	if _, err := npx(grammarRoot, append([]string{"tree-sitter-cli@" + version, "generate"}, args...)...); err != nil {
		return fmt.Errorf("tree-sitter-cli@%s generate: %w; if this release cannot generate ABI %d, pass -tree-sitter-cli <older version>", version, err, maxABI)
	}
	return nil
}

// patchTargets lists the paths a unified diff names, read from its own `---`
// and `+++` headers and stripped of the usual one-level prefix. git apply is
// what applies the patch; this only needs to know which files it touches.
func patchTargets(patchFile string) ([]string, error) {
	data, err := os.ReadFile(patchFile)
	if err != nil {
		return nil, err
	}
	var out []string
	for _, line := range strings.Split(string(data), "\n") {
		var prefix string
		switch {
		case strings.HasPrefix(line, "--- "):
			prefix = "a/"
		case strings.HasPrefix(line, "+++ "):
			prefix = "b/"
		default:
			continue
		}
		target := line[4:]
		// diff -u writes a timestamp after a tab; git apply ignores it.
		if tab := strings.IndexByte(target, '\t'); tab >= 0 {
			target = target[:tab]
		}
		target = strings.TrimSpace(target)
		// A creation names /dev/null on the old side, a deletion on the new
		// side. Both sides are read so either way the real path is seen.
		if target == "" || target == "/dev/null" {
			continue
		}
		target = path.Clean(strings.TrimPrefix(target, prefix))
		if !slices.Contains(out, target) {
			out = append(out, target)
		}
	}
	return out, nil
}

// vendoredDirectly reports whether vendor copies the file at this path, which
// is relative to the grammar directory, straight into the grammar folder.
// Everything else a patch touches -- grammar.js above all -- reaches the
// vendored grammar only through a regenerated parser.
func vendoredDirectly(rel string) bool {
	dir, name := path.Split(rel)
	upper := strings.ToUpper(name)
	if strings.HasPrefix(upper, "LICENSE") || strings.HasPrefix(upper, "COPYING") {
		return dir == ""
	}
	switch dir {
	case "src/":
		return name == "parser.c" || name == "scanner.c" || strings.HasSuffix(name, ".h")
	case "src/tree_sitter/":
		return strings.HasSuffix(name, ".h")
	}
	return false
}

// patchPathsNeedingGeneration lists the paths a patch touches whose effect is
// lost unless the parser is regenerated. A patch that only edits vendored
// files is a complete change on its own; one that edits grammar.js is not.
func patchPathsNeedingGeneration(patchFile string) ([]string, error) {
	targets, err := patchTargets(patchFile)
	if err != nil {
		return nil, err
	}
	var out []string
	for _, t := range targets {
		if !vendoredDirectly(t) {
			out = append(out, t)
		}
	}
	return out, nil
}

// recordedLocalBuild is the local_build block a finished generation writes back
// to the manifest: the exact version that ran, and nothing else new.
//
// GenerateArgs deliberately keeps only what the entry already asked for. The
// args actually passed to generate come from generateArgs, which falls back to
// --abi maxABI; recording that fallback would turn a derived default into an
// explicit pin, and the next runtime bump would edit the one constant while
// every grammar went on generating the old ABI -- which vendor keeps accepting
// for as long as it is inside the range, so nothing would fail.
func recordedLocalBuild(build *LocalBuild, version string) *LocalBuild {
	next := LocalBuild{}
	if build != nil {
		next = *build
	}
	next.TreeSitterCLI = version
	return &next
}
	args := []string{"apply"}
	if subdir != "" {
		args = append(args, "--directory="+filepath.ToSlash(subdir))
	}
	args = append(args, "--", patchFile)
	cmd := exec.Command("git", args...)
	cmd.Dir = checkout
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("apply %s: %w\n%s", patchFile, err, strings.TrimSpace(string(out)))
	}
	return nil
}

var errNoNPX = errors.New("tree-sitter generation needs Node.js; npx was not found on PATH")

// npx and findNPX are variables so tests can stand in for Node.
var (
	npx     = runNPX
	findNPX = func() error {
		if _, err := exec.LookPath("npx"); err != nil {
			return errNoNPX
		}
		return nil
	}
)

func runNPX(dir string, args ...string) (string, error) {
	cmd := exec.Command("npx", append([]string{"--yes"}, args...)...)
	cmd.Dir = dir
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	if errors.Is(err, exec.ErrNotFound) {
		err = errNoNPX
	}
	return strings.TrimSpace(string(out)), err
}
package main

import (
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
)

const addPatchedLine = `diff --git a/src/parser.c b/src/parser.c
--- a/src/parser.c
+++ b/src/parser.c
@@ -1 +1,2 @@
 #define LANGUAGE_VERSION 14
+// patched
`

func patchManifest(t *testing.T, repo, subdir, patchPath, patch string) (manifest, root string) {
	t.Helper()
	root = t.TempDir()
	manifest = filepath.Join(root, "grammars.json")
	if err := saveManifest(manifest, []Grammar{{
		Language:   "demo",
		URL:        repo,
		Reference:  "v0",
		Revision:   "0000000",
		Path:       subdir,
		Files:      []string{"LICENSE", "parser.c"},
		ABI:        14,
		LocalBuild: &LocalBuild{Patch: patchPath},
	}}); err != nil {
		t.Fatal(err)
	}
	if filepath.IsLocal(patchPath) {
		writeTestFile(t, filepath.Join(root, patchPath), patch)
	}
	writeTestFile(t, filepath.Join(root, "demo", "parser.c"), "old\n")
	return manifest, root
}

func TestRefreshAppliesPatch(t *testing.T) {
	repo, _ := generatedGrammarRepo(t)
	manifest, root := patchManifest(t, repo, "", "demo/fix.patch", addPatchedLine)
	if err := refresh(options{Lang: "demo", Ref: "HEAD", ManifestPath: manifest, GrammarsDir: root}); err != nil {
		t.Fatal(err)
	}
	if got, _ := os.ReadFile(filepath.Join(root, "demo", "parser.c")); !strings.Contains(string(got), "// patched") {
		t.Fatalf("vendored parser.c lacks the patch: %q", got)
	}
	grammars, err := loadManifest(manifest)
	if err != nil {
		t.Fatal(err)
	}
	if lb := grammars[0].LocalBuild; lb == nil || lb.Patch != "demo/fix.patch" {
		t.Fatalf("local_build not kept: %+v", grammars[0])
	}
}

func TestRefreshAppliesPatchInSubdir(t *testing.T) {
	repo := gitRepo(t, map[string]string{"sub/src/parser.c": "#define LANGUAGE_VERSION 14\n", "LICENSE": "MIT\n"})
	manifest, root := patchManifest(t, repo, "sub", "demo/fix.patch", addPatchedLine)
	if err := refresh(options{Lang: "demo", Ref: "HEAD", ManifestPath: manifest, GrammarsDir: root}); err != nil {
		t.Fatal(err)
	}
	if got, _ := os.ReadFile(filepath.Join(root, "demo", "parser.c")); !strings.Contains(string(got), "// patched") {
		t.Fatalf("vendored parser.c lacks the patch: %q", got)
	}
}

func TestRefreshPatchFailureLeavesVendorUntouched(t *testing.T) {
	repo, _ := generatedGrammarRepo(t)
	mismatch := strings.Replace(addPatchedLine, "VERSION 14", "VERSION 13", 1)
	manifest, root := patchManifest(t, repo, "", "demo/fix.patch", mismatch)
	before, _ := os.ReadFile(manifest)
	err := refresh(options{Lang: "demo", Ref: "HEAD", ManifestPath: manifest, GrammarsDir: root})
	if err == nil || !strings.Contains(err.Error(), "fix.patch") {
		t.Fatalf("err = %v; want a failure naming fix.patch", err)
	}
	if got, _ := os.ReadFile(filepath.Join(root, "demo", "parser.c")); string(got) != "old\n" {
		t.Fatalf("parser.c changed after a failed patch: %q", got)
	}
	if after, _ := os.ReadFile(manifest); string(after) != string(before) {
		t.Fatalf("manifest changed after a failed patch:\n%s", after)
	}
}

func TestRefreshRejectsUnsafePatchPath(t *testing.T) {
	for _, patch := range []string{"../x.patch", "/tmp/x.patch"} {
		manifest, root := patchManifest(t, filepath.Join(t.TempDir(), "no-such-repo"), "", patch, "")
		err := refresh(options{Lang: "demo", Ref: "HEAD", ManifestPath: manifest, GrammarsDir: root})
		if err == nil || !strings.Contains(err.Error(), "patch") || strings.Contains(err.Error(), "fetch") {
			t.Errorf("patch %q: err = %v; want a patch validation error before any fetch", patch, err)
		}
	}
}

// patchGrammarJS edits the grammar, not a vendored file, so it changes nothing
// about the vendored folder unless the parser is regenerated from it.
const patchGrammarJS = `diff --git a/grammar.js b/grammar.js
--- a/grammar.js
+++ b/grammar.js
@@ -1 +1,2 @@
 module.exports = grammar({});
+// patched
`

func grammarJSRepo(t *testing.T) string {
	t.Helper()
	return gitRepo(t, map[string]string{
		"grammar.js":   "module.exports = grammar({});\n",
		"src/parser.c": "#define LANGUAGE_VERSION 14\n",
		"LICENSE":      "MIT\n",
	})
}

// #357 vendored a Swift parser built from a hand-applied grammar.js patch, and
// nothing in the tree tied the two together. Applying that patch and then
// copying upstream's committed parser.c is the same silent loss, reported as a
// success, so it is refused instead.
func TestRefreshRefusesAPatchThatNeedsGeneration(t *testing.T) {
	manifest, root := patchManifest(t, grammarJSRepo(t), "", "demo/fix.patch", patchGrammarJS)
	before, err := os.ReadFile(manifest)
	if err != nil {
		t.Fatal(err)
	}
	err = refresh(options{Lang: "demo", Ref: "HEAD", ManifestPath: manifest, GrammarsDir: root})
	if err == nil {
		t.Fatal("want a refusal: the patch edits grammar.js and nothing regenerates the parser")
	}
	for _, want := range []string{"grammar.js", "tree_sitter_cli", "-generate"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("err = %v; want it to name %q", err, want)
		}
	}
	if got, _ := os.ReadFile(filepath.Join(root, "demo", "parser.c")); string(got) != "old\n" {
		t.Errorf("parser.c changed after the refusal: %q", got)
	}
	if after, _ := os.ReadFile(manifest); string(after) != string(before) {
		t.Errorf("manifest changed after the refusal:\n%s", after)
	}
}

// The other direction: the same patch with a generator recorded is the
// supported arrangement, and must not be refused.
func TestRefreshAcceptsAGrammarPatchThatRegenerates(t *testing.T) {
	calls := fakeNPX(t, "0.24.7", "14")
	root := t.TempDir()
	manifest := filepath.Join(root, "grammars.json")
	if err := saveManifest(manifest, []Grammar{{
		Language:  "demo",
		URL:       grammarJSRepo(t),
		Reference: "v0",
		Revision:  "0000000",
		Files:     []string{"LICENSE", "parser.c"},
		ABI:       14,
		LocalBuild: &LocalBuild{
			Patch:         "demo/fix.patch",
			TreeSitterCLI: "0.24.7",
		},
	}}); err != nil {
		t.Fatal(err)
	}
	writeTestFile(t, filepath.Join(root, "demo", "fix.patch"), patchGrammarJS)
	writeTestFile(t, filepath.Join(root, "demo", "parser.c"), "old\n")
	if err := refresh(options{Lang: "demo", Ref: "HEAD", ManifestPath: manifest, GrammarsDir: root}); err != nil {
		t.Fatalf("a patched grammar with a recorded generator was refused: %v", err)
	}
	if len(*calls) == 0 {
		t.Fatal("the parser was never regenerated")
