// patchGrammarJS edits the grammar, not a vendored file, so it changes nothing
// about the vendored folder unless the parser is regenerated from it.
const patchGrammarJS = `diff --git a/grammar.js b/grammar.js
--- a/grammar.js
+++ b/grammar.js
@@ -1 +1,2 @@
