package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// The ABI range the go-tree-sitter runtime loads. maxABI is also what
// grammars are generated for. TestABIRangeMatchesRuntime fails when a
// go-tree-sitter upgrade changes the range, so this is the one place to edit.
const (
	minABI = 13
	maxABI = 14
)

// Grammar is one vendored grammar's origin, as recorded in grammars.json.
type Grammar struct {
	Language   string      `json:"language"`
	URL        string      `json:"url"`
	Reference  string      `json:"reference"`
	Revision   string      `json:"revision"`
	Path       string      `json:"path,omitempty"`
	Files      []string    `json:"files"`
	ABI        int         `json:"abi"`
	Note       string      `json:"note,omitempty"`
	LocalBuild *LocalBuild `json:"local_build,omitempty"`
}

// LocalBuild is how grammar-refresh turns the upstream checkout into the
// vendored files: Patch (relative to the grammars directory) is applied
// first, then the parser is regenerated when TreeSitterCLI is set.
type LocalBuild struct {
	Patch         string   `json:"patch,omitempty"`
	TreeSitterCLI string   `json:"tree_sitter_cli,omitempty"`
	GenerateArgs  []string `json:"generate_args,omitempty"`
}

// abiError is a generated parser.c the go-tree-sitter runtime cannot load.

//
// The vendored src/parser.c must be within the ABI range the go-tree-sitter
// runtime loads (minABI-maxABI). A manifest entry's local_build block, or
// -generate, builds it instead of copying it: the entry's patch is applied to
// the checkout, then `npx tree-sitter-cli@<version> generate <args>` runs
// (default --abi maxABI), which needs Node.js. The recorded revision
// regenerates with the recorded version; a new revision uses @latest and
// records the version it ran. -tree-sitter-cli pins one, which is the fix if
// a future tree-sitter release stops generating maxABI. binding.go is never
// touched, so a new language still needs one. A grammar that changes parse
// results needs an IdentityRevision bump (internal/sem/provider.go) in the
// same commit. An entry's note survives every refresh.
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"os/exec"
